def reverse_with_stack(s: str) -> str:
    stack = []
    for char in s:
        stack.append(char)
    reversed_str = []
    while stack:
        reversed_str.append(stack.pop())
    return ''.join(reversed_str)

print(reverse_with_stack('Antigravity'))

def is_valid_parentheses(s: str) -> bool:
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack

print('()[]{} ->', is_valid_parentheses('()[]{}'))
print('(] ->', is_valid_parentheses('(]'))
print('([{}]) ->', is_valid_parentheses('([{}])'))

