from collections import deque

class TaskQueue:
    def __init__(self):
        self.q = deque()
    def enqueue(self, task_id: str, payload: dict):
        self.q.append({'id': task_id, 'data': payload})
    def process_next(self):
        if not self.q:
            return None
        task = self.q.popleft()
        return f'Processed task {task["id"]} with data {task["data"]}'

